import ts from 'typescript';

/** The document's two local-font classes are generated by Next, not arbitrary
 * page styling. This exact new array-join form has no other object consumer or
 * write; the historical template expression is not certified by this form. */
export function ownedRootFontClasses(file, expression, tree) {
  if (file !== 'web/app/layout.tsx' || !expression || !ts.isCallExpression(expression) || expression.arguments.length !== 1 || expression.arguments[0].getText(tree) !== "' '") return false;
  const callee = expression.expression;
  if (!ts.isPropertyAccessExpression(callee) || callee.name.text !== 'join' || !ts.isArrayLiteralExpression(callee.expression)) return false;
  const values = callee.expression.elements;
  if (values.length !== 2 || values.map(value=>value.getText(tree)).join('|') !== 'lexendDeca.variable|arabic.variable') return false;
  if (!tree.statements.some(statement=>ts.isImportDeclaration(statement) && statement.moduleSpecifier.text === 'next/font/local' && statement.importClause?.name?.text === 'localFont' && !statement.importClause.namedBindings)) return false;
  const expected = new Map([
    ['lexendDeca', "localFont({ src: './fonts/lexend-deca.ttf', variable: '--font-lexend-deca', weight: '100 900', display: 'swap', adjustFontFallback: false, fallback: [] })"],
    ['arabic', "localFont({ src: './fonts/noto-sans-arabic.ttf', variable: '--font-arabic', weight: '100 900', display: 'swap', preload: false })"],
  ]);
  for (const [name, initializer] of expected) {
    const declarations = tree.statements.filter(ts.isVariableStatement).flatMap(statement=>statement.declarationList.flags & ts.NodeFlags.Const ? [...statement.declarationList.declarations] : []);
    if (declarations.filter(node=>node.name.getText(tree) === name && node.initializer?.getText(tree) === initializer).length !== 1) return false;
  }
  const references = {lexendDeca:0,arabic:0,localFont:0};
  const walk = node=>{if (ts.isIdentifier(node) && node.text in references) references[node.text]++;ts.forEachChild(node,walk);};walk(tree);
  return references.lexendDeca === 2 && references.arabic === 2 && references.localFont === 3;
}
